class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int sum = 0;
        for (int num : nums) sum += num;
        if ((sum + target) % 2 != 0 || Math.abs(target) > sum) return 0;
        int s = (sum + target) / 2;
        int[] dp = new int[s + 1];
        dp[0] = 1;
        for (int num : nums) {
            for (int j = s; j >= num; j--) {
                dp[j] += dp[j - num];
            }
        }
        return dp[s];
    }
}

class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        java.util.Map<String, Integer> memo = new java.util.HashMap<>();
        return dfs(nums, 0, 0, target, memo);
    }

    private int dfs(int[] nums, int i, int sum, int target, java.util.Map<String, Integer> memo) {
        if (i == nums.length) return sum == target ? 1 : 0;
        String key = i + "," + sum;
        if (memo.containsKey(key)) return memo.get(key);
        int result = dfs(nums, i + 1, sum + nums[i], target, memo)
                   + dfs(nums, i + 1, sum - nums[i], target, memo);
        memo.put(key, result);
        return result;
    }
}
